meta.customCss:
/* ─── atracoes.html — fichas dos lugares ─── */
.filtros { display: flex; flex-wrap: wrap; gap: .5rem; margin: 0 0 2rem; }
.filtro-btn {
  font: inherit; font-size: .85rem; font-weight: 600; cursor: pointer;
  padding: .45rem .9rem; border-radius: 999px;
  border: 1px solid var(--border); background: var(--surface); color: var(--text-muted);
  transition: background .15s, color .15s, border-color .15s;
}
.filtro-btn:hover { border-color: var(--primary); color: var(--text); }
.filtro-btn.ativo { background: var(--primary); border-color: var(--primary); color: var(--white); }

.dia-bloco { margin: 0 0 2.75rem; }
.dia-cab { margin: 0 0 1rem; }
.dia-tit {
  display: flex; align-items: center; gap: .6rem; flex-wrap: wrap;
  margin: 0 0 .35rem; font-size: 1.25rem;
}
.dia-chip {
  font-size: .72rem; font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
  padding: .25rem .6rem; border-radius: 999px;
  background: var(--bg-alt); color: var(--primary); border: 1px solid var(--border);
}
.dia-ancora { margin: 0; font-size: .9rem; color: var(--text-muted); }

.opt-grid {
  display: grid; gap: 1rem;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
}
.opt-card {
  border: 1px solid var(--border); border-left: 3px solid var(--border);
  border-radius: var(--radius); background: var(--surface); padding: 1rem 1.1rem;
}
.opt-card.sel-ok { border-left-color: var(--ok); }
.opt-card.sel-duv { border-left-color: var(--warn); }
.opt-card.sel-conf { border-left-color: var(--danger); }
.opt-top {
  display: flex; align-items: center; justify-content: space-between;
  gap: .5rem; margin: 0 0 .5rem;
}
.opt-selo { font-size: .75rem; font-weight: 700; color: var(--text-muted); }
.sel-ok .opt-selo { color: var(--ok); }
.sel-duv .opt-selo { color: var(--warn); }
.sel-conf .opt-selo { color: var(--danger); }
.opt-tipo {
  font-size: .68rem; font-weight: 700; letter-spacing: .05em; text-transform: uppercase;
  color: var(--text-light);
}
.opt-nome { margin: 0 0 .3rem; font-size: 1rem; line-height: 1.35; }
.opt-onde { margin: 0 0 .5rem; font-size: .8rem; font-weight: 600; color: var(--primary); }
.opt-nota { margin: 0; font-size: .88rem; line-height: 1.55; color: var(--text-muted); }

.rest-lista { margin: .5rem 0 0; padding-left: 1.1rem; }
.rest-lista li { font-size: .88rem; line-height: 1.6; color: var(--text-muted); }

@media (max-width: 640px) {
  .opt-grid { grid-template-columns: 1fr; }
  .filtros { gap: .4rem; }
  .filtro-btn { font-size: .8rem; padding: .4rem .75rem; }
}

/* níveis de recomendação */
.opt-rec { font-size: .72rem; font-weight: 800; letter-spacing: .02em; }
.opt-rec.rec1 { color: var(--ok); }
.opt-rec.rec2 { color: var(--primary); }
.opt-rec.rec3 { color: var(--text-muted); }
.opt-rec.rec4 { color: var(--warn); }
.opt-card { border-left-color: var(--border); }
.opt-selo { font-weight: 700; }
.sel-ok .opt-selo { color: var(--ok); }
.sel-duv .opt-selo { color: var(--warn); }
.sel-conf .opt-selo { color: var(--danger); }
.legenda { display: flex; flex-wrap: wrap; gap: .35rem 1.1rem; margin: .9rem 0 0; }
.leg-item { font-size: .8rem; color: var(--text-muted); }
.leg-item b { margin-right: .2rem; }
.opt-onde { display: block; }


/* ─── barra de filtros combinados ─── */
.filtro-barra {
  border: 1px solid var(--border); border-radius: var(--radius);
  background: var(--bg-alt); padding: 1rem 1.1rem .35rem; margin: 0 0 2rem;
}
.filtro-grupo { display: flex; align-items: baseline; gap: .85rem; margin: 0 0 .35rem; }
.filtro-rot {
  flex: 0 0 6.5rem; font-size: .7rem; font-weight: 700;
  letter-spacing: .07em; text-transform: uppercase; color: var(--text-light);
}
.filtro-barra .filtros { margin: 0 0 .55rem; }
.filtro-n {
  display: inline-block; margin-left: .3rem; padding: 0 .35rem;
  border-radius: 999px; background: var(--bg-alt);
  font-size: .7rem; font-weight: 700; color: var(--text-light);
}
.filtro-btn.ativo .filtro-n { background: rgba(255, 255, 255, .22); color: var(--white); }
.rec-btn.rec1:not(.ativo) { color: var(--ok); }
.rec-btn.rec2:not(.ativo) { color: var(--primary); }
.rec-btn.rec4:not(.ativo) { color: var(--warn); }
.filtro-saida {
  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
  margin: .25rem 0 .65rem; font-size: .8rem; color: var(--text-muted);
}
.filtro-limpa {
  font: inherit; font-size: .78rem; cursor: pointer; padding: 0;
  border: 0; background: none; color: var(--primary); text-decoration: underline;
}
.dia-vazio { display: none; margin: 0; font-size: .85rem; color: var(--text-light); font-style: italic; }
.dia-bloco.sem-resultado .dia-vazio { display: block; }
.dia-bloco.sem-resultado .opt-grid { display: none; }

/* ─── links de blog e vídeo dentro do card ─── */
.opt-links {
  display: flex; flex-wrap: wrap; gap: .35rem;
  margin: .85rem 0 0; padding-top: .75rem; border-top: 1px solid var(--border);
}
.opt-link {
  display: inline-block; max-width: 100%; overflow: hidden;
  text-overflow: ellipsis; white-space: nowrap;
  font-size: .74rem; font-weight: 600; text-decoration: none;
  padding: .28rem .6rem; border-radius: 999px;
  border: 1px solid var(--border); background: var(--bg-alt); color: var(--text-muted);
  transition: border-color .15s, color .15s;
}
.opt-link:hover { border-color: var(--primary); color: var(--primary); }
.opt-link.video { color: var(--danger); }
.opt-link.video:hover { border-color: var(--danger); }
.opt-link.insta { color: var(--link); }
.opt-link.insta:hover { border-color: var(--link); }
/* a marca do Instagram vai como SVG embutido: acompanha a cor do chip e
   sobrevive nas páginas offline, onde nenhuma fonte de ícone chegaria */
.opt-link.insta { gap: .38rem; }
.ico-insta { flex: 0 0 auto; vertical-align: -2px; }

@media (max-width: 640px) {
  .filtro-grupo { display: block; }
  .filtro-rot { display: block; margin: 0 0 .35rem; }
  .filtro-barra { padding: .9rem .8rem .3rem; }
  .opt-link { font-size: .72rem; }
}

/* ─── alvos de toque de 44px nos filtros ─── */
/* o restante dos ajustes de acessibilidade vive no theme.css da skill */
.filtro-btn { min-height: 44px; display: inline-flex; align-items: center; }
.filtro-limpa { min-height: 44px; }
.opt-link { min-height: 40px; display: inline-flex; align-items: center; padding: .4rem .7rem; }

/* ─── cards de atração com foto ─── */
.opt-card { display: flex; flex-direction: column; padding: 0; overflow: hidden; }
.opt-corpo { padding: 1rem 1.1rem 1.15rem; display: flex; flex-direction: column; flex: 1; }
.opt-foto {
  position: relative; aspect-ratio: 3 / 2; background: var(--bg-alt);
  border-bottom: 1px solid var(--border);
}
.opt-foto img { width: 100%; height: 100%; object-fit: cover; display: block; }
/* sem foto o card não pode virar um buraco na grade: um degradê da paleta
   segura o ritmo da coluna */
.opt-foto.sem-foto {
  aspect-ratio: 5 / 1;
  background: linear-gradient(120deg, var(--primary), var(--primary-light) 60%, var(--secondary));
}
/* crédito obrigatório das licenças CC, sem roubar a foto */
.opt-foto-cred {
  position: absolute; right: 8px; bottom: 8px;
  display: inline-flex; align-items: center; justify-content: center;
  width: 30px; height: 30px; border-radius: 50%; text-decoration: none;
  font-size: .8rem; line-height: 1;
  background: rgba(255, 255, 255, .85); border: 1px solid var(--border);
}
.opt-foto-cred:hover { background: var(--white); }
.opt-nota { flex: 1; }
/* a âncora vinda do roteiro não pode parar embaixo do menu fixo */
.opt-card { scroll-margin-top: calc(var(--nav-h) + 16px); }
.opt-card:target { border-color: var(--accent); border-left-color: var(--accent); box-shadow: var(--shadow-lg); }
